// backend/src/models/labs.js
// ---------------------------------------------------------------------------
// Labs are the federated-learning nodes and the points plotted on the NIH map.
// The `geom` column is generated by Postgres from latitude/longitude, so we
// never write it directly.
// ---------------------------------------------------------------------------
const { query } = require('../db/pool');

async function create({
  name, limsType = null, district, province,
  latitude, longitude, flClientId = null,
}) {
  const { rows } = await query(
    `INSERT INTO labs (name, lims_type, district, province, latitude, longitude, fl_client_id)
     VALUES ($1, $2, $3, $4, $5, $6, $7)
     RETURNING *`,
    [name, limsType, district, province, latitude, longitude, flClientId]
  );
  return rows[0];
}

async function findById(id) {
  const { rows } = await query('SELECT * FROM labs WHERE id = $1', [id]);
  return rows[0] || null;
}

/** Resolve a lab from the id a Flower client authenticates with (Module 4). */
async function findByFlClientId(flClientId) {
  const { rows } = await query('SELECT * FROM labs WHERE fl_client_id = $1', [flClientId]);
  return rows[0] || null;
}

async function list() {
  const { rows } = await query(
    'SELECT * FROM labs ORDER BY province, district, name'
  );
  return rows;
}

module.exports = { create, findById, findByFlClientId, list };
